def review(u):
    if u['status']!='U':return
    text=u['text'];s=u['section']
    # These are visual labels/diagram examples, not standalone requirements.
    if re.search(r'DES(?:\s+DES){3,}|^Set PDA Enum|^Power Ramp Reset|^Reset Initialization|^CMD WRITE|^ECS CMD|^\(Read Pattern\)',text):
        u['kind']='fragment';u.update(status='E',scope='structure',reason='타이밍 그림의 신호/명령 라벨이다. 원문 교차 확인을 위해 보존하되 문장 분모에는 포함하지 않는다.',method='visual-label');return
    if re.search(r'for ease of illustration|for clarity of illustration|just examples|only for illustration|These parameters are verified by design|Measured (?:over|for|at)|measurement.*VDD|proper setting.*determined by the memory controller|controller locks DQS',text,re.I) or re.match(r'^(?:NOTE\s*\d+\s*|\d+\.\s*)?(?:Please refer|See |Refer |Figure.*shows|An example|Timing diagram|The details.*following|This is described)',text,re.I):
        u.update(status='E',scope='informative',reason='그림 예시·참조·측정 방법 또는 host의 설정 선택 설명이다. 실제 기능·타이밍 조건은 인접 항목에서 따로 평가한다.',method='reviewed-scope');return
    for sec,pat,st,reason,ev in R:
        if starts(s,sec) and pat.search(text):
            u.update(status=st,scope='informative' if st=='E' else 'digital',reason=reason,evidence=ev,method='reviewed-statement');return
